// Settings. Landledger's console, for the Explore link; which Landfall entities are services; and Landfall's names for
// services that Landledger's Explore names differently (Landfall name → Landledger name).
const LANDLEDGER_CONSOLE_URL = 'http://localhost:4811';
const SERVICE_KINDS = ['service'];
const SERVICE_NAMES = {};
return { ...$json, settings: { consoleUrl: LANDLEDGER_CONSOLE_URL.replace(/\/+$/, ''), serviceKinds: SERVICE_KINDS, serviceNames: SERVICE_NAMES } };

