// The incident's services and window, from the room (not the poll's copy). Services: the alert's entity, entities
// attached to the room, and service:<name> hints on its triggers, when their kind is a service. The window: from the
// room's opening to the status change that ended it (or now, if none is in the timeline).
const { incident: seen, settings } = $('Settings').first().json;
const room = $input.first().json;
const events = room.events ?? [];
const ENDED = ['resolved', 'closed', 'mitigated', 'recovered', 'done', 'archived'];
const kinds = settings.serviceKinds.map((k) => k.toLowerCase());
const names = new Set();
const add = (kind, id) => { if (kind && id && kinds.includes(String(kind).toLowerCase())) names.add(settings.serviceNames[id] ?? String(id)); };
const hints = (list) => { for (const h of Array.isArray(list) ? list : []) { const i = String(h).indexOf(':'); if (i > 0) add(String(h).slice(0, i), String(h).slice(i + 1).trim()); } };
add(seen.alertEntity?.kind, seen.alertEntity?.id);
if (seen.alertContext && typeof seen.alertContext === 'object') hints(seen.alertContext.entityHints);
for (const e of events) {
  const p = e.payload ?? {};
  if (e.type === 'context.attached') add(p.kind ?? p.entity?.kind, p.id ?? p.entity?.id);
  add(p.entity?.kind, p.entity?.id);
  hints(p.entityHints);
}
const opened = events.find((e) => e.type === 'incident.opened');
const from = seen.createdAt ?? opened?.occurredAt;
const end = [...events].reverse().find((e) => e.type === 'status.changed' && ENDED.includes(String(e.payload?.status ?? '').toLowerCase()));
const to = end?.occurredAt ?? new Date().toISOString();
const services = [...names].sort();
return [{ json: {
  route: services.length && from && Date.parse(from) < Date.parse(to) ? 0 : 1,
  incidentId: seen.id,
  displayId: seen.displayId ?? room.incident?.displayId ?? seen.id,
  title: seen.title ?? room.incident?.title ?? '',
  status: end?.payload?.status ?? room.incident?.status ?? seen.status,
  services,
  from,
  to,
  consoleUrl: settings.consoleUrl,
} }];

