// The note: the cost during the incident, labelled estimated, per service, with a link to Landledger's Explore. Posted
// as a room note, because the landfall plugin can't write a postmortem section.
const w = $('Window and services').first().json;
const cost = $input.first().json;
const usd = (v) => `$${Number(v).toFixed(2)}`;
const at = (iso) => new Date(iso).toISOString().slice(0, 16).replace('T', ' ');
const minutes = Math.round((Date.parse(w.to) - Date.parse(w.from)) / 60000);
const span = minutes >= 60 ? `${Math.floor(minutes / 60)} h ${minutes % 60} min` : `${minutes} min`;
const lines = (cost.services ?? []).map((s) => (s.known ? `- ${s.service}: ${usd(s.amount)}` : `- ${s.service}: no cost in Landledger under this name`));
const month = w.from.slice(0, 7);
const explore = `${w.consoleUrl}/explore?by=service&month=${month}&filter=${encodeURIComponent(w.services.map((s) => `service:${s}`).join(','))}`;
const text = [
  `Estimated cost during this incident: ${usd(cost.total)} (USD), ${at(w.from)} to ${at(w.to)} UTC (${span}).`,
  ...lines,
  `Estimated: each day's cost in Landledger, by the share of the day inside the incident's window. Not an invoiced figure.`,
  `Explore in Landledger: ${explore}`,
  `Posted by Landflow as a room note: it can't write a postmortem section.`,
].join('\n');
return { incidentId: w.incidentId, text, total: cost.total, services: cost.services, from: w.from, to: w.to, explore };
